def _clamp_int(value):
    """Clamp a built-in integer to 0..100 inclusive.

    Rejects booleans and non-built-in-integer inputs with TypeError.
    With no argument (value=42) returns 42.
    """
    if isinstance(value, bool):
        raise TypeError("bool is not a built-in integer")
    if not isinstance(value, int):
        raise TypeError("expected built-in integer")
    if value < 0:
        return 0
    if value > 100:
        return 100
    return value"}]}

